# Go Example Code: Cache Package Usage

Based on the API surface and overview documentation, here are common usage patterns for the `cache` package:

## Basic Operations Example

```go
package main

import (
	"fmt"
	"time"
	"yourmodule/cache"
)

func main() {
	// Create a cache with 5-minute TTL
	c := cache.New(5 * time.Minute)

	// Set values
	c.Set("user:1", map[string]string{"name": "Alice", "email": "alice@example.com"})
	c.Set("user:2", map[string]string{"name": "Bob", "email": "bob@example.com"})

	// Get a value
	if value, exists := c.Get("user:1"); exists {
		fmt.Printf("Found user: %v\n", value)
	}

	// Check non-existent key
	if _, exists := c.Get("user:999"); !exists {
		fmt.Println("User not found in cache")
	}

	// Delete a specific entry
	c.Delete("user:2")

	// Clear entire cache
	c.Purge()
}
```

## Session Storage Example

```go
package main

import (
	"fmt"
	"time"
	"yourmodule/cache"
)

type Session struct {
	UserID    string
	Token     string
	CreatedAt time.Time
}

func main() {
	// Create cache with 1-hour TTL for sessions
	sessionCache := cache.New(1 * time.Hour)

	// Store user session
	session := Session{
		UserID:    "user:123",
		Token:     "abc123xyz",
		CreatedAt: time.Now(),
	}
	sessionCache.Set("session:abc123xyz", session)

	// Retrieve session
	if cachedSession, exists := sessionCache.Get("session:abc123xyz"); exists {
		sess := cachedSession.(Session)
		fmt.Printf("Session valid for user: %s\n", sess.UserID)
	}

	// Session automatically expires after 1 hour
}
```

## Rate Limiting Example

```go
package main

import (
	"fmt"
	"sync"
	"time"
	"yourmodule/cache"
)

type RateLimiter struct {
	cache      *cache.Cache
	maxRequests int
	mu         sync.Mutex
}

func NewRateLimiter(maxRequests int, window time.Duration) *RateLimiter {
	return &RateLimiter{
		cache:       cache.New(window),
		maxRequests: maxRequests,
	}
}

func (rl *RateLimiter) AllowRequest(clientID string) bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	var count int
	if val, exists := rl.cache.Get(clientID); exists {
		count = val.(int)
	}

	if count >= rl.maxRequests {
		return false
	}

	rl.cache.Set(clientID, count+1)
	return true
}

func main() {
	// Create rate limiter: 10 requests per minute per client
	limiter := NewRateLimiter(10, 1*time.Minute)

	clientID := "client:456"

	for i := 1; i <= 12; i++ {
		if limiter.AllowRequest(clientID) {
			fmt.Printf("Request %d: allowed\n", i)
		} else {
			fmt.Printf("Request %d: rate limited\n", i)
		}
	}
}
```

## Concurrent Access Example

```go
package main

import (
	"fmt"
	"sync"
	"time"
	"yourmodule/cache"
)

func main() {
	c := cache.New(10 * time.Minute)
	var wg sync.WaitGroup

	// Multiple goroutines writing to cache
	for i := 1; i <= 5; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			c.Set(fmt.Sprintf("key:%d", id), fmt.Sprintf("value:%d", id))
		}(i)
	}

	// Multiple goroutines reading from cache
	for i := 1; i <= 5; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			if val, exists := c.Get(fmt.Sprintf("key:%d", id)); exists {
				fmt.Printf("Read: %v\n", val)
			}
		}(i)
	}

	wg.Wait()
	fmt.Println("All concurrent operations completed safely")
}
```

## Computed Result Caching Example

```go
package main

import (
	"fmt"
	"time"
	"yourmodule/cache"
)

type DataFetcher struct {
	cache *cache.Cache
}

func NewDataFetcher() *DataFetcher {
	// Cache results for 30 minutes
	return &DataFetcher{cache: cache.New(30 * time.Minute)}
}

func (df *DataFetcher) expensiveComputation(userID string) interface{} {
	// Check cache first
	if cached, exists := df.cache.Get(userID); exists {
		fmt.Printf("Cache hit for %s\n", userID)
		return cached
	}

	// Simulate expensive operation
	fmt.Printf("Computing result for %s...\n", userID)
	time.Sleep(100 * time.Millisecond)
	result := map[string]interface{}{
		"id":    userID,
		"score": 95,
		"data":  "expensive computation result",
	}

	// Cache the result
	df.cache.Set(userID, result)
	return result
}

func main() {
	fetcher := NewDataFetcher()

	// First call: computes and caches
	fetcher.expensiveComputation("user:1")

	// Second call: retrieves from cache
	fetcher.expensiveComputation("user:1")

	// Third call: different user, computes and caches
	fetcher.expensiveComputation("user:2")
}
```

