## 5. **RequestHandler Interface (Orchestrator)**
```go
type RequestHandler interface {
  Handle(req Request) Response
}

type UserRequestHandler struct {
  validator  Validator
  normalizer Normalizer
  repository UserRepository
  notifier   Notifier
}

func (h *UserRequestHandler) Handle(req Request) Response {
  if err := h.validator.Validate(req); err != nil {
    return Response{Error: err.Error()}
  }

  h.normalizer.Normalize(&req)

  user := h.repository.FindOrCreate(req.Name, req.Email)
  user.Age = req.Age
  user, err := h.repository.Save(user)
  if err != nil {
    return Response{Error: err.Error()}
  }

  h.notifier.Notify(user)

  return Response{UserID: user.ID}
}
```

