## Recommended Refactoring Structure

### Extract into separate functions:

```go
// 1. Validation layer
func validateRequest(req Request) error {
  if req.Name == "" { return errors.New("name required") }
  if req.Age < 0 { return errors.New("invalid age") }
  if req.Email == "" { return errors.New("email required") }
  return nil
}

// 2. Normalization layer
func normalizeRequest(req *Request) {
  req.Name = strings.TrimSpace(req.Name)
  req.Email = strings.ToLower(req.Email)
}

// 3. User service layer
func createOrUpdateUser(req Request) (User, error) {
  user := db.FindOrCreate(req.Name, req.Email)
  user.Age = req.Age
  return user, db.Save(user)
}

// 4. Notification layer
func notifyUserCreated(user User) error {
  return mailer.Send(user.Email, "Welcome", "Hello "+user.Name)
}

// 5. Analytics layer
func trackUserCreated(userID string) {
  analytics.Track("user_created", userID)
}

// 6. Orchestrator (refactored main function)
func handleRequest(req Request) Response {
  if err := validateRequest(req); err != nil {
    return Response{Error: err.Error()}
  }

  normalizeRequest(&req)

  user, err := createOrUpdateUser(req)
  if err != nil {
    return Response{Error: "failed to create user"}
  }

  notifyUserCreated(user)
  trackUserCreated(user.ID)

  return Response{UserID: user.ID}
}
```

## Benefits

✅ Single Responsibility Principle - each function has one reason to change  
✅ Testability - each concern can be tested independently  
✅ Reusability - functions can be used in other contexts  
✅ Maintainability - easier to modify individual concerns  
✅ Error handling - can be improved per layer

