type DefaultUserService struct {
	validator   RequestValidator
	normalizer  RequestNormalizer
	repository  UserRepository
	notifier    UserNotifier
	logger      Logger
}

func NewDefaultUserService(
	validator RequestValidator,
	normalizer RequestNormalizer,
	repository UserRepository,
	notifier UserNotifier,
	logger Logger,
) *DefaultUserService {
	return &DefaultUserService{
		validator:   validator,
		normalizer:  normalizer,
		repository:  repository,
		notifier:    notifier,
		logger:      logger,
	}
}

func (s *DefaultUserService) HandleRequest(req Request) (Response, error) {
	// Step 1: Validate
	if err := s.validator.Validate(req); err != nil {
		return Response{Error: err.Error()}, err
	}

	// Step 2: Normalize
	s.normalizer.Normalize(&req)

	// Step 3: Process - Find or Create User
	user, err := s.repository.FindOrCreate(req.Name, req.Email)
	if err != nil {
		s.logger.Errorf("failed to find or create user: %v", err)
		return Response{Error: "user operation failed"}, err
	}

	// Step 4: Update User Data
	user.Age = req.Age

	// Step 5: Persist to Database
	if err := s.repository.Save(user); err != nil {
		s.logger.Errorf("failed to save user: %v", err)
		return Response{Error: "save operation failed"}, err
	}

	// Step 6: Notify (non-blocking failure)
	if err := s.notifier.Notify(user); err != nil {
		s.logger.Warnf("notification failed for user %s: %v", user.ID, err)
		// Don't fail the request due to notification errors
	}

	return Response{UserID: user.ID}, nil
}
```

