### Fix 4: File Type Validation

**Vulnerability:** CWE-434 (Unrestricted File Upload)

```go
// FIXED CODE
import "net/http"

func isAllowedFileType(header *multipart.FileHeader, file multipart.File) bool {
    // Check Content-Type header
    allowedMimeTypes := map[string]bool{
        "application/pdf":        true,
        "image/jpeg":            true,
        "image/png":             true,
        "application/msword":    true,
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document": true,
    }

    contentType := header.Header.Get("Content-Type")
    if !allowedMimeTypes[contentType] {
        return false
    }

    // Verify magic bytes (file signature)
    buffer := make([]byte, 512)
    n, _ := file.Read(buffer)
    file.Seek(0, 0) // Reset file pointer

    // Magic byte checks
    validMagic := false
    if bytes.HasPrefix(buffer[:n], []byte("%PDF")) {
        validMagic = true
    }
    if bytes.HasPrefix(buffer[:n], []byte{0xFF, 0xD8, 0xFF}) { // JPEG
        validMagic = true
    }
    if bytes.HasPrefix(buffer[:n], []byte{0x89, 0x50, 0x4E, 0x47}) { // PNG
        validMagic = true
    }

    return validMagic
}

// Usage:
if !isAllowedFileType(header, file) {
    logSecurityEvent("invalid_file_type", user.ID, header.Header.Get("Content-Type"))
    http.Error(w, "File type not allowed", http.StatusBadRequest)
    return
}
```

