			// Check error expectation
			if (err != nil) != tt.shouldErr {
				t.Errorf("unexpected error state: got error=%v, want error=%v",
					err != nil, tt.shouldErr)
			}

			// Check error message if error expected
			if tt.shouldErr && err != nil && err.Error() != tt.errMsg {
